def _update_policy_periodically(self) -> None:
    last = time.time()
    while not self._end_flag:
        cur = time.time()
        interval = cur - last
        if interval < self._cfg.update_policy_second:
            time.sleep(self._cfg.update_policy_second * 0.1)
            continue
        else:
            self._update_policy()
            last = time.time()

